/**
 * Provider-scoped Firebase Secret attachment. All paid-order worker features
 * remain in the existing engine; disabled providers must not block deployment
 * by requiring unrelated secrets that don't exist in this Firebase project.
 *
 * The profile is generated by scripts/prepare-firebase.mjs from functions/.env,
 * contains NO credentials, and is packed with the Functions deployment.
 */
import {readFileSync} from 'node:fs';
const LYRICS=new Set(['openai','gemini','mureka']);
const MUSIC=new Set(['','mureka','google_lyria']);
export function enabledFunctionSecrets(profile){
 if(!profile||profile.schemaVersion!==1
  ||!LYRICS.has(profile.lyricsProvider)
  ||!MUSIC.has(profile.musicProvider)
  ||typeof profile.artistResearch!=='boolean'
  ||typeof profile.driveBackup!=='boolean'
  ||typeof profile.resendWebhook!=='boolean')
  throw new Error('Invalid nonsecret Firebase deployment profile');
 const api=['TOSS_SECRET_KEY','RESEND_API_KEY','WITHU_LINK_ENCRYPTION_KEY',
  'MUREKA_API_KEY','WITHU_VIDEO_LEAD_HMAC_KEY','WITHU_SUPPORT_HMAC_KEY'];
 if(profile.resendWebhook)api.push('RESEND_WEBHOOK_SIGNING_SECRET');
 const worker=['RESEND_API_KEY','WITHU_LINK_ENCRYPTION_KEY','MUREKA_API_KEY'];
 if(profile.lyricsProvider==='openai')worker.push('OPENAI_API_KEY');
 if(profile.lyricsProvider==='gemini'
  ||profile.artistResearch||profile.musicProvider==='google_lyria')
  worker.push('GEMINI_API_KEY');
 if(profile.driveBackup)worker.push('WITHU_DRIVE_SERVICE_ACCOUNT_JSON');
 return Object.freeze({api:Object.freeze(api),worker:Object.freeze(worker)});
}
export function readDeploymentSecretProfile(){
 // In the packed app this path resolves to functions/deployment-profile.json.
 // Missing profile is a deployment error, NOT permission to default providers.
 const raw=readFileSync(new URL('../deployment-profile.json',import.meta.url),'utf8');
 const profile=JSON.parse(raw);
 enabledFunctionSecrets(profile);
 return profile;
}
